import Image from "next/image"

import blurMap from "@/lib/blur-map.json"

// Every photograph on the site goes through here, so Next can serve
// AVIF/WebP at the size the viewport actually needs. The masters are
// 1600×1200; before this wrapper existed they were sent raw to phones
// (146–513 KB each, measured 2.8 MB on /projects — see docs/perf).
//
// Static photos also get a build-time blur placeholder: a ~10px webp of
// the image itself, generated by scripts/generate-blur-map.mjs (runs as
// `prebuild`) into src/lib/blur-map.json, keyed by public path. When a
// src has an entry the photo fades in over a soft wash of its own
// colours instead of popping in. Editor-uploaded Blob URLs have no
// entry and simply skip the treatment — never let a missing key break
// rendering.
//
// Always rendered with `fill` inside an already-positioned frame (the
// site's photos live in aspect-ratio containers under the `photo-glass`
// screen), so
// callers keep full control of cropping via object-* classes.
export function Photo({
  src,
  alt,
  className,
  sizes = "100vw",
  priority = false,
}: {
  src: string
  alt: string
  className?: string
  /** Rendered width per breakpoint — wrong values mean wasted bytes. */
  sizes?: string
  /** Only for images above the fold; never more than one or two. */
  priority?: boolean
}) {
  const blurDataURL = (blurMap as Record<string, string>)[src]
  return (
    <Image
      src={src}
      alt={alt}
      fill
      sizes={sizes}
      priority={priority}
      draggable={false}
      className={className}
      {...(blurDataURL ? { placeholder: "blur" as const, blurDataURL } : {})}
    />
  )
}
